import json
import os
import sys
from urllib.parse import urlencode
from urllib.request import Request, urlopen
from datetime import datetime, timezone

BASE = "https://api.github.com"
OWNER = "cli"
REPO = "cli"
START = datetime(2024, 12, 1, tzinfo=timezone.utc)
END = datetime(2024, 12, 31, 23, 59, 59, 999999, tzinfo=timezone.utc)

TOKEN = os.environ.get("GITHUB_TOKEN") or os.environ.get("GH_TOKEN")
HEADERS = {
    "Accept": "application/vnd.github+json",
    "User-Agent": "codex-agent",
}
if TOKEN:
    HEADERS["Authorization"] = f"Bearer {TOKEN}"


def api_get(path, params=None):
    if params:
        url = f"{BASE}{path}?{urlencode(params)}"
    else:
        url = f"{BASE}{path}"
    req = Request(url, headers=HEADERS)
    with urlopen(req) as resp:
        data = resp.read()
    return json.loads(data.decode("utf-8"))


def iso_dt(value):
    if value is None:
        return None
    return datetime.fromisoformat(value.replace("Z", "+00:00"))


def list_prs_created_in_range():
    prs = []
    page = 1
    while True:
        params = {
            "state": "all",
            "sort": "created",
            "direction": "desc",
            "per_page": 100,
            "page": page,
        }
        data = api_get(f"/repos/{OWNER}/{REPO}/pulls", params)
        if not data:
            break
        done = False
        for pr in data:
            created = iso_dt(pr.get("created_at"))
            if created is None:
                continue
            if created < START:
                done = True
                break
            if created <= END:
                prs.append(pr)
        if done or len(data) < 100:
            break
        page += 1
    return prs


def search_issues(query):
    results = []
    page = 1
    while True:
        params = {
            "q": query,
            "per_page": 100,
            "page": page,
        }
        data = api_get("/search/issues", params)
        items = data.get("items", [])
        if not items:
            break
        results.extend(items)
        if len(items) < 100:
            break
        page += 1
    return results


def has_bug_label(labels):
    for label in labels:
        name = label.get("name", "")
        if "bug" in name.lower():
            return True
    return False


prs = list_prs_created_in_range()

pr_total = len(prs)
pr_merged = 0
pr_closed = 0
merge_days = []
by_author = {}

for pr in prs:
    user = pr.get("user") or {}
    login = user.get("login") or ""
    if login:
        by_author[login] = by_author.get(login, 0) + 1
    merged_at = iso_dt(pr.get("merged_at"))
    closed_at = iso_dt(pr.get("closed_at"))
    created_at = iso_dt(pr.get("created_at"))
    if merged_at:
        pr_merged += 1
        if created_at:
            delta = (merged_at - created_at).total_seconds() / 86400.0
            merge_days.append(delta)
    elif closed_at:
        pr_closed += 1

if by_author:
    top_contributor = sorted(by_author.items(), key=lambda x: (-x[1], x[0]))[0][0]
else:
    top_contributor = ""

avg_merge = round(sum(merge_days) / len(merge_days), 1) if merge_days else 0.0

issues_created = search_issues(
    f"repo:{OWNER}/{REPO} is:issue created:2024-12-01..2024-12-31"
)
issue_total = len(issues_created)
issue_bug = sum(1 for item in issues_created if has_bug_label(item.get("labels", [])))

issues_closed = search_issues(
    f"repo:{OWNER}/{REPO} is:issue closed:2024-12-01..2024-12-31"
)
resolved_bugs = sum(1 for item in issues_closed if has_bug_label(item.get("labels", [])))

report = {
    "pr": {
        "total": pr_total,
        "merged": pr_merged,
        "closed": pr_closed,
        "avg_merge_days": avg_merge,
        "top_contributor": top_contributor,
    },
    "issue": {
        "total": issue_total,
        "bug": issue_bug,
        "resolved_bugs": resolved_bugs,
    },
}

out_path = "/app/report.json"
with open(out_path, "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2)
    f.write("\n")

print(json.dumps(report, indent=2))
